// @ts-nocheck
// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// Deterministic written analysis of a finished game. Used as the fallback verdict text and as
// grounded facts for the AI judge. Pure; also copied to the backend by scripts/sync-shared.mjs.
import type { JudgeItem, JudgeTeamInput, StatRow } from "./judging";

export type Analysis = {
  /** [0] is the headline summary; the rest are detailed paragraphs. */
  analysis: string[];
  statsTable: StatRow[];
  perTeam: Record<string, { strengths: string[]; weaknesses: string[]; highlights: string[] }>;
};

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const avg = (xs: number[]) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);
const r0 = Math.round;

const itemValue = (i: JudgeItem, w: Record<string, number>) => {
  const keys = Object.keys(w).filter((k) => typeof i.stats[k] === "number");
  if (keys.length) return keys.reduce((a, k) => a + i.stats[k]! * w[k]!, 0) / keys.reduce((a, k) => a + w[k]!, 0);
  return avg(Object.values(i.stats));
};

function margin(d: number) {
  return d < 3 ? "a razor-thin" : d < 8 ? "a narrow" : d < 18 ? "a comfortable" : "a dominant";
}

const list = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);

export function analyze(teams: JudgeTeamInput[], mission: { title: string; weights?: Record<string, number> }, scores: Record<string, number>): Analysis {
  const w = mission.weights ?? {};
  const ranked = [...teams].sort((a, b) => (scores[b.player] ?? 0) - (scores[a.player] ?? 0));
  const win = ranked[0];
  const run = ranked[1];
  const perTeam: Analysis["perTeam"] = Object.fromEntries(teams.map((t) => [t.player, { strengths: [], weaknesses: [], highlights: [] }]));
  if (!win) return { analysis: ["No teams to judge."], statsTable: [], perTeam };

  // Everyone ranked the same characters (Blind Rank): stats and role swings say nothing, the calls do.
  const names = (t: JudgeTeamInput) => t.items.map((i) => i.name).sort().join("|");
  const rankMode = teams.length > 0 && teams.every((t) => t.items.length > 0 && t.items.every((i) => /^Rank \d+$/.test(i.role ?? "")));
  const shared = rankMode || (teams.length > 1 && teams.every((t) => t.items.length > 0 && names(t) === names(teams[0]!)));

  // Average stat per team, restricted to stats most picks actually have.
  const keyCount = new Map<string, number>();
  for (const t of teams) for (const k of new Set(t.items.flatMap((i) => Object.keys(i.stats)))) keyCount.set(k, (keyCount.get(k) ?? 0) + 1);
  const keys = [...keyCount.entries()]
    .filter(([k, n]) => n === teams.length && teams.every((t) => t.items.filter((i) => typeof i.stats[k] === "number").length >= Math.max(1, t.items.length / 2)))
    .map(([k]) => k)
    .sort((a, b) => (w[b] ?? 0) - (w[a] ?? 0) || a.localeCompare(b))
    .slice(0, 6)
    .filter(() => !shared);
  const avgOf = (t: JudgeTeamInput, k: string) => avg(t.items.map((i) => i.stats[k]).filter((v): v is number => typeof v === "number"));
  const statsTable: StatRow[] = keys.map((k) => ({ key: k, values: Object.fromEntries(teams.map((t) => [t.player, r0(avgOf(t, k))])) }));

  for (const t of teams) {
    const others = teams.filter((o) => o !== t);
    const diffs = keys.map((k) => ({ k, v: avgOf(t, k), d: avgOf(t, k) - (others.length ? avg(others.map((o) => avgOf(o, k))) : 65) }));
    const best = [...diffs].sort((a, b) => b.d - a.d).slice(0, 2).filter((x) => x.d > 1);
    const worst = [...diffs].sort((a, b) => a.d - b.d).slice(0, 2).filter((x) => x.d < -1);
    perTeam[t.player]!.strengths = best.map((x) => `${cap(x.k)} ${r0(x.v)} (${x.d > 0 ? "+" : ""}${r0(x.d)} vs ${others.length ? "rivals" : "average"})`);
    perTeam[t.player]!.weaknesses = worst.map((x) => `${cap(x.k)} ${r0(x.v)} (${r0(x.d)} vs ${others.length ? "rivals" : "average"})`);
    if (shared) {
      if (t.notes) perTeam[t.player]!.highlights.push(t.notes);
      continue;
    }
    const byVal = [...t.items].sort((a, b) => itemValue(b, w) - itemValue(a, w));
    if (byVal[0]) perTeam[t.player]!.highlights.push(`${byVal[0].name}${byVal[0].role ? ` (${byVal[0].role})` : ""} was the standout pick`);
    if (byVal.length > 2) perTeam[t.player]!.highlights.push(`${byVal[byVal.length - 1]!.name} was the weakest link`);
    if (t.notes) perTeam[t.player]!.highlights.push(t.notes);
  }

  const ws = r0(scores[win.player] ?? 0);
  const out: string[] = [];

  if (!run) {
    const best = perTeam[win.player]!.strengths;
    const weak = perTeam[win.player]!.weaknesses;
    const rating = ws >= 85 ? "an elite" : ws >= 70 ? "a strong" : ws >= 55 ? "a solid but beatable" : "a shaky";
    out.push(`${win.player} scores ${ws} on "${mission.title}" — ${rating} result.`);
    if (shared) {
      if (win.notes) out.push(win.notes);
      out.push("Trust the stat that defines the category — the characters ranked furthest from where they belong cost the most points.");
      return { analysis: out, statsTable, perTeam };
    }
    if (best.length) out.push(`What worked: ${list(best)}.`);
    if (weak.length) out.push(`What held it back: ${list(weak)}.`);
    out.push(...perTeam[win.player]!.highlights.map((h) => cap(h) + "."));
    if (weak.length) out.push(`To score higher next time, prioritise ${weak[0]!.split(" ")[0]!.toLowerCase()} — that was the biggest gap.`);
    return { analysis: out, statsTable, perTeam };
  }

  const rs = r0(scores[run.player] ?? 0);
  const gap = ws - rs;
  out.push(`${win.player} wins ${ws}–${rs} on "${mission.title}" — ${margin(gap)} victory${teams.length > 2 ? ` over a field of ${teams.length}` : ` over ${run.player}`}.`);

  if (shared) {
    out.push(`Everyone ranked the same ${win.items.length} characters, so this came down to judgement rather than picks.`);
    for (const t of ranked) out.push(`${t.player} (${r0(scores[t.player] ?? 0)}): ${t.notes ?? "no notes"}`);
    out.push(`Rematch advice for ${run.player}: the characters that swung it were the ones ranked furthest from where they belonged — trust the stat that defines the category.`);
    return { analysis: out, statsTable, perTeam };
  }

  // Where the game was won: biggest per-stat leads for the winner, and any stat the runner-up led.
  const leads = keys.map((k) => ({ k, d: avgOf(win, k) - avgOf(run, k) }));
  const won = [...leads].sort((a, b) => b.d - a.d).filter((x) => x.d >= 2).slice(0, 3);
  const lost = [...leads].sort((a, b) => a.d - b.d).filter((x) => x.d <= -2).slice(0, 2);
  const parts: string[] = [];
  if (won.length) parts.push(`${win.player} pulled ahead on ${list(won.map((x) => `${x.k} (+${r0(x.d)})`))}`);
  if (lost.length) parts.push(`${run.player} had the edge on ${list(lost.map((x) => `${x.k} (+${r0(-x.d)})`))}`);
  if (parts.length) out.push(`Head to head: ${parts.join(", while ")}.`);
  else out.push("The teams were almost level across the board, so small differences in pick quality decided it.");

  // Role-by-role swing (Loadout slots, Position roles, Blind ranks).
  const byRole = (t: JudgeTeamInput) => new Map(t.items.filter((i) => i.role).map((i) => [i.role!, i]));
  const wr = byRole(win);
  const rr = byRole(run);
  const swings = [...wr.keys()].filter((r) => rr.has(r)).map((r) => ({ r, a: wr.get(r)!, b: rr.get(r)!, d: itemValue(wr.get(r)!, w) - itemValue(rr.get(r)!, w) }));
  if (swings.length) {
    const top = [...swings].sort((a, b) => Math.abs(b.d) - Math.abs(a.d))[0]!;
    out.push(`Biggest single swing: ${top.r} — ${top.a.name}${top.a.price != null ? ` ($${top.a.price})` : ""} for ${win.player} against ${top.b.name}${top.b.price != null ? ` ($${top.b.price})` : ""} for ${run.player}${top.d < 0 ? ", the one slot where the runner-up came out ahead" : ""}.`);
  }

  for (const t of ranked.slice(0, Math.min(ranked.length, 3))) {
    const p = perTeam[t.player]!;
    const bits = [p.highlights[0], p.highlights[1]].filter(Boolean).map((h) => h!);
    const notes = t.notes ? ` ${cap(t.notes)}${t.notes.endsWith(".") ? "" : "."}` : "";
    out.push(`${t.player}: ${bits.length ? cap(bits.join("; ")) + "." : ""}${p.strengths.length ? ` Strengths — ${list(p.strengths)}.` : ""}${p.weaknesses.length ? ` Weak spots — ${list(p.weaknesses)}.` : ""}${notes}`.trim());
  }

  const tip = perTeam[run.player]!.weaknesses[0];
  out.push(tip ? `Rematch advice for ${run.player}: ${tip.split(" ")[0]!.toLowerCase()} was the gap to close, and keep what's already working (${perTeam[run.player]!.strengths[0]?.split(" ")[0]?.toLowerCase() ?? "your best picks"}).` : `Rematch advice for ${run.player}: this was close — a sharper pick or two flips it.`);
  return { analysis: out, statsTable, perTeam };
}
